create extension if not exists pgcrypto;
create table if not exists public.quizzes (id uuid primary key default gen_random_uuid(),title text not null,description text,status text not null default 'DRAFT' check (status in ('DRAFT','REGISTRATION_OPEN','REGISTRATION_CLOSED','WAITING','LIVE','PAUSED','COMPLETED','RESULTS_PUBLISHED')),registration_open boolean not null default false,is_public boolean not null default true,max_participants integer not null default 1000 check (max_participants between 1 and 5000),starts_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.participants (id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,participant_code text not null unique,full_name text not null,dob date not null,club_name text not null,city text,email text,mobile text,status text not null default 'REGISTERED' check (status in ('REGISTERED','WAITING','ACTIVE','DISCONNECTED','COMPLETED','DISQUALIFIED')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists participants_quiz_idx on public.participants(quiz_id); create index if not exists participants_code_idx on public.participants(participant_code);
create table if not exists public.questions (id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,question_number integer not null,question_text text not null,option_a text not null,option_b text not null,option_c text not null,option_d text not null,correct_option text not null check (correct_option in ('A','B','C','D')),points integer not null default 10,time_limit_seconds integer not null default 15 check (time_limit_seconds between 5 and 300),image_url text,category text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(quiz_id,question_number));
create index if not exists questions_quiz_idx on public.questions(quiz_id,question_number);
create table if not exists public.quiz_state (quiz_id uuid primary key references public.quizzes(id) on delete cascade,status text not null default 'WAITING' check (status in ('WAITING','LIVE','PAUSED','COMPLETED','RESULTS_PUBLISHED')),current_question_id uuid references public.questions(id) on delete set null,question_started_at timestamptz,question_ends_at timestamptz,updated_at timestamptz not null default now());
create table if not exists public.sessions (id uuid primary key default gen_random_uuid(),participant_id uuid not null references public.participants(id) on delete cascade,session_token_hash text not null,device_identifier text,active boolean not null default true,created_at timestamptz not null default now(),last_seen_at timestamptz not null default now());
create index if not exists sessions_participant_idx on public.sessions(participant_id,active);
create table if not exists public.answers (id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,participant_id uuid not null references public.participants(id) on delete cascade,question_id uuid not null references public.questions(id) on delete cascade,selected_option text not null check (selected_option in ('A','B','C','D')),is_correct boolean not null,points_awarded integer not null default 0,answered_at timestamptz not null default now(),response_time_ms bigint not null default 0,created_at timestamptz not null default now(),unique(participant_id,question_id));
create index if not exists answers_quiz_idx on public.answers(quiz_id); create index if not exists answers_participant_idx on public.answers(participant_id);
create table if not exists public.final_results (id uuid primary key default gen_random_uuid(),quiz_id uuid not null references public.quizzes(id) on delete cascade,participant_id uuid not null references public.participants(id) on delete cascade,score integer not null default 0,correct_count integer not null default 0,wrong_count integer not null default 0,unanswered_count integer not null default 0,total_response_time_ms bigint not null default 0,rank integer,created_at timestamptz not null default now(),unique(quiz_id,participant_id));
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
alter table public.quizzes enable row level security; alter table public.participants enable row level security; alter table public.questions enable row level security; alter table public.quiz_state enable row level security; alter table public.sessions enable row level security; alter table public.answers enable row level security; alter table public.final_results enable row level security; alter table public.admin_users enable row level security;
create policy "public can read public quiz" on public.quizzes for select using (is_public=true); create policy "admins manage quizzes" on public.quizzes for all using (public.is_admin()) with check (public.is_admin());
create policy "admins read participants" on public.participants for select using (public.is_admin()); create policy "admins manage participants" on public.participants for all using (public.is_admin()) with check (public.is_admin());
create policy "admins manage questions" on public.questions for all using (public.is_admin()) with check (public.is_admin());
create policy "public reads active quiz state" on public.quiz_state for select using (true); create policy "admins manage state" on public.quiz_state for all using (public.is_admin()) with check (public.is_admin());
create policy "admins read sessions" on public.sessions for select using (public.is_admin()); create policy "admins manage sessions" on public.sessions for all using (public.is_admin()) with check (public.is_admin());
create policy "admins read answers" on public.answers for select using (public.is_admin()); create policy "admins manage answers" on public.answers for all using (public.is_admin()) with check (public.is_admin());
create policy "public reads published results" on public.final_results for select using (exists(select 1 from public.quizzes q where q.id=quiz_id and q.status='RESULTS_PUBLISHED')); create policy "admins manage results" on public.final_results for all using (public.is_admin()) with check (public.is_admin());
create policy "admins read own admin membership" on public.admin_users for select using (user_id=auth.uid() or public.is_admin());
alter publication supabase_realtime add table public.quiz_state;
insert into public.quizzes(title,description,status,registration_open,is_public,max_participants) select 'International Service Quiz 2026','Live quiz by Rotaract Club of Madras Millenia','REGISTRATION_OPEN',true,true,1000 where not exists(select 1 from public.quizzes);
insert into public.quiz_state(quiz_id,status) select id,'WAITING' from public.quizzes q where not exists(select 1 from public.quiz_state s where s.quiz_id=q.id);
